// Offline geometric case coverage. No native travel or runtime geometry drawing.
#define main LegacyCoreCaseMain
#include "test_core.cpp"
#undef main
int main(int argc,char**argv){try{
 Check(argc==3,"usage layer-cases baseline-pack report");fs::path root=fs::absolute(argv[1]);auto index_bytes=Read(root/"atlas2-index.json");auto index=Json::parse(index_bytes);Json rows=Json::array();size_t poses=0,boundaries=0,slopes=0,overlaps=0,hysteresis=0;
 for(const auto& entry:index["areas"]){std::string area=entry["area"];auto manifest_bytes=Read(root/area/"manifest.json");Check(Hash(manifest_bytes)==entry["manifest_sha256"].get<std::string>(),"manifest identity");auto manifest=Json::parse(manifest_bytes);auto bytes=Read(root/area/"grid.json");Check(Hash(bytes)==manifest["grid_sha256"].get<std::string>(),"grid identity");Grid g;g.FromJson(Json::parse(bytes));std::vector<std::vector<int>> ids(g.anchors.size());for(int i=0;i<int(g.surfaces.size());++i)ids[g.surfaces[i].layer].push_back(i);Json layers=Json::array();
  auto compare=[&](float x,float y,float z){Check(g.Select(x,y,z)==Reference(g,x,y,z),"geometric case disagrees with strict V1 rule reproduction");++poses;};
  for(int li=0;li<int(ids.size());++li){Json row={{"layer_id","F"+std::string(3-std::to_string(li).size(),'0')+std::to_string(li)},{"boundary",false},{"height_varying_surface",false},{"distinct_height_overlap",false},{"real_overlap_hysteresis",false}};if(ids[li].empty()){layers.push_back(row);continue;}
   for(int id:ids[li]){const auto&s=g.surfaces[id];float bx=(s.v[0]+s.v[2])*.5f,bz=(s.v[1]+s.v[3])*.5f,by;if(!Height(s,bx,bz,by))continue;for(float dy:{-.1f,0.f,.1f})compare(bx,by+dy,bz);row["boundary"]=true;++boundaries;break;}
   int slope=-1;float variation=.01f;for(int id:ids[li]){const auto&s=g.surfaces[id];float center_height;float delta=*std::max_element(s.y.begin(),s.y.end())-*std::min_element(s.y.begin(),s.y.end());if(delta>variation&&Height(s,(s.v[0]+s.v[2]+s.v[4])/3,(s.v[1]+s.v[3]+s.v[5])/3,center_height)){variation=delta;slope=id;}}
   if(slope>=0){const auto&s=g.surfaces[slope];for(const auto&w:std::array<std::array<float,3>,3>{{{1.f/3,1.f/3,1.f/3},{.6f,.2f,.2f},{.2f,.6f,.2f}}}){float x=0,y=0,z=0;for(int k=0;k<3;++k){x+=s.v[2*k]*w[k];z+=s.v[2*k+1]*w[k];y+=s.y[k]*w[k];}for(float dy:{-.1f,0.f,.1f})compare(x,y+dy,z);}row["height_varying_surface"]=true;++slopes;}
   const size_t samples=std::min<size_t>(16,ids[li].size());row["overlap_centroids_searched"]=samples;
   for(size_t sample=0;sample<samples;++sample){int id=ids[li][samples==1?0:sample*(ids[li].size()-1)/(samples-1)];const auto&s=g.surfaces[id];float x=(s.v[0]+s.v[2]+s.v[4])/3,z=(s.v[1]+s.v[3]+s.v[5])/3,y; if(!Height(s,x,z,y))continue;auto cell=g.cells.find({int(std::floor(x/g.cell)),int(std::floor(z/g.cell))});if(cell==g.cells.end())continue;std::map<int,std::vector<float>> heights;
    for(int candidate:cell->second){const auto&other=g.surfaces[candidate];float height;if(Height(other,x,z,height)){auto&values=heights[other.layer];if(std::none_of(values.begin(),values.end(),[&](float old){return std::abs(old-height)<.001f;}))values.push_back(height);}}
    int other_layer=-1;float other_y=0,gap=INFINITY;for(const auto&[layer,values]:heights)if(layer!=li)for(float height:values)if(std::abs(height-y)>.05f&&std::abs(height-y)<gap){other_layer=layer;other_y=height;gap=std::abs(height-y);}if(other_layer<0)continue;
    for(float level:{y,other_y,(y+other_y)*.5f})for(float dy:{-.01f,0.f,.01f})compare(x,level+dy,z);row["distinct_height_overlap"]=true;row["overlap_vertical_gap"]=gap;++overlaps;
    // Exactly two single-height authored layers permit a clear jitter/transition assertion.
    if(heights.size()==2&&heights.begin()->second.size()==1&&heights.rbegin()->second.size()==1&&gap>1){float low=std::min(y,other_y),high=std::max(y,other_y),mid=(low+high)*.5f;int prior=g.Select(x,low,z);Check(prior==Reference(g,x,low,z),"lower overlap floor");for(float dy:{-.1f,.1f,-.1f,.1f})Check(g.Select(x,mid+dy,z,prior,.35f)==prior,"real overlap jitter changed hysteresis floor");Check(g.Select(x,high,z,prior,.35f)==Reference(g,x,high,z),"real overlap did not transition outside hysteresis margin");row["real_overlap_hysteresis"]=true;++hysteresis;}
    break;
   }layers.push_back(row);
  }rows.push_back({{"area",area},{"grid_sha256",manifest["grid_sha256"]},{"layers",layers}});std::cout<<"LAYER_CASE_AREA "<<area<<" layers="<<layers.size()<<"\n"<<std::flush;
 }
 Json report={{"schema",1},{"pass",true},{"baseline_index_sha256",Hash(index_bytes)},{"areas",rows},{"strict_comparison_poses",poses},{"layers_with_boundary_case",boundaries},{"layers_with_height_varying_surface",slopes},{"layers_with_sampled_distinct_height_overlap",overlaps},{"real_two_layer_hysteresis_cases",hysteresis},{"native_gameplay_tested",false},{"overlap_search_bound_per_layer",16},{"scope","Offline geometric samples compared with independent strict V1 rule reproduction. Height variation is not a semantic staircase label. A missing overlap means not found in the bounded centroid sample; not proof that no overlap exists."}};WriteJson(argv[2],report);std::cout<<"LAYER_CASE_PASS poses="<<poses<<" boundary_layers="<<boundaries<<" height_variation_layers="<<slopes<<" overlap_layers="<<overlaps<<" hysteresis="<<hysteresis<<"\n";return 0;
}catch(const std::exception&e){std::cout<<"LAYER_CASE_FAIL "<<e.what()<<"\n";return 1;}}
